package android.widget;
public class ViewAnimator extends FrameLayout { public ViewAnimator(android.content.Context c) { super(c); } public ViewAnimator(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public ViewAnimator(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public ViewAnimator(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } private int displayed; public void setDisplayedChild(int n) { displayed=n; for(int i=0;i<getChildCount();i++) getChildAt(i).setVisibility(i==n?VISIBLE:GONE); } public int getDisplayedChild() { return displayed; } public void showNext() { if(getChildCount()>0) setDisplayedChild((displayed+1)%getChildCount()); } public void showPrevious() { if(getChildCount()>0) setDisplayedChild((displayed+getChildCount()-1)%getChildCount()); } }
